sys_script_client.script:
function onChange(control, oldValue, newValue, isLoading, isTemplate) {
    if (isLoading || newValue === '') {
        //var sourceSystem = g_scratchpad.trdSourceSystem.toString();
        if (g_form.getValue('trade_task_type').toString() == 'Maker' && newValue == '') {
            //setOnLoadTaskForm(false);

        }
        return;
    }


    var swiftRef = 'GB-HBEU-' + newValue;
    var isValidSourceSystem = g_scratchpad.validSourceSystemGCS;

    if ((newValue != oldValue) && (isValidSourceSystem.toString() == 'true')) {
        var gcsData = new GlideAjax('x_hsb11_mss_c_proc.GCSTradeDetailsUtils');
        gcsData.addParam('sysparm_name', 'getTradeDataforGCSUK');
        gcsData.addParam('sysparm_trdID', swiftRef);
        gcsData.getXMLAnswer(handleResponse);
    }

    function handleResponse(response) {
        var trdDetails = JSON.parse(response);

        //actual values from trade
        var transactionType = trdDetails.transactType; //Transaction Type
        var contractType = trdDetails.contractType; // Contract Type
        var reasonCodeDCC = trdDetails.rCodeDCC; // Reason code for DCC UK swift
        var reasonCodeGC = trdDetails.rCodeGC; // Reason code for GC UK swift
        var fxLoc = trdDetails.fxLocation;
        //actual values from trade

        if (isValidSourceSystem.toString() == 'true') {
            var market = g_scratchpad.owningBus;
            var outcome = g_form.getValue('outcome').toString();
            if (outcome == "Put 'Trade on Hold'") {
                putTradeOnHold();
            } else if ((outcome == "Settle Trade")) {

                g_form.setValue('settlement_type', 'B'); // Set settlement type default as B for Settle Trade Outcome
                g_form.setReadOnly('settlement_type', true);
                g_form.setMandatory('cancellation_reference', false);
                g_form.setDisplay('cancellation_reference', false);
                g_form.setMandatory('settlement_date', false);
                g_form.setMandatory('value_date', false);
                g_form.setDisplay('value_date', true);
                g_form.setDisplay('settlement_date', true);
                g_form.setMandatory('bk_to_bk_info', false);
                g_form.setDisplay('bk_to_bk_info', false);
                g_form.setDisplay('advice', true); //MSSCUSTODY-4883
                g_form.setReadOnly('advice', true); //MSSCUSTODY-4883

                if ((transactionType == 'DVP' || transactionType == 'RVP') && (contractType == 'A')) {
                    settleTrade();
                } else if ((transactionType != 'DVP' || transactionType != 'RVP') && (contrType == 'A')) {
                    g_form.setMandatory('value_date', false);
                    g_form.setDisplay('value_date', true);
                } else {
                    g_form.setReadOnly('value_date', true); // Make Value Date Read Only //MSSCUSTODY-4883
                }

            } else if (outcome == "Confirm Trade") {
                g_form.setMandatory('value_date', false);
                g_form.setDisplay('value_date', true);
                if ((transactionType == 'DVP' || transactionType == 'RVP') && (contractType == 'C')) {
                    confirmTrade();
                } else if ((transactionType != 'DVP' || transactionType != 'RVP') && (contrType == 'C')) {
                    g_form.setMandatory('value_date', false);
                    g_form.setDisplay('value_date', true);
                } else {
                    g_form.setReadOnly('value_date', true); //MSSCUSTODY-4883
                }
            } else if (outcome == "Process Trade Cancellation") {
                processTradeCancellation(market, reasonCodeDCC, reasonCodeGC, fxLoc);
            } else {

                setOnLoadTaskForm(false);
                onLoadHide(false);
            }
        }
        //Type appropriate comment here, and begin script below

        function setOnLoadTaskForm(out_1) {

            g_form.setMandatory('settlement_date', out_1);
            g_form.setMandatory('value_date', out_1);
            g_form.setMandatory('fxr_td', out_1);
            g_form.setMandatory('reason_code', out_1);
            g_form.setMandatory('settlement_type', out_1);
            g_form.setMandatory('cancellation_reference', out_1);
            g_form.setMandatory('bk_to_bk_info', out_1);

            g_form.setDisplay('settlement_date', out_1);
            g_form.setDisplay('value_date', out_1);
            g_form.setDisplay('fxr_td', out_1);
            g_form.setDisplay('reason_code', out_1);
            g_form.setDisplay('settlement_type', out_1);
            g_form.setDisplay('cancellation_reference', out_1);
            g_form.setDisplay('bk_to_bk_info', out_1);

            g_form.clearValue('value_date');
            g_form.clearValue('settlement_date');
            g_form.clearValue('fxr_td');
            g_form.clearValue('reason_code');
            g_form.clearValue('reason_description');
            g_form.clearValue('settlement_type');
            g_form.clearValue('cancellation_reference');
            g_form.clearValue('bk_to_bk_info');

        }

        function putTradeOnHold() {

            // Enable fields for Put trade On Hold Outcome
            g_form.setValue('suspend', 'Y');
            g_form.setReadOnly('suspend', true);
            g_form.setMandatory('reason_code', true);
            g_form.setLabelOf('reason_code', 'Further Identification Code');
            g_form.setDisplay('reason_code', true);

            // Disabling fields for Put Trade on Hold
            g_form.setValue('settlement_type', '');
            g_form.setMandatory('value_date', false);
            g_form.setDisplay('value_date', false);
            g_form.setMandatory('settlement_date', false);
            g_form.setDisplay('settlement_date', false);
            g_form.setValue('reason_code', '');
            g_form.setValue('reason_description', '');
            g_form.setMandatory('fxr_td', false);
            g_form.setDisplay('fxr_td', false);
            g_form.setMandatory('cancellation_reference', false);
            g_form.setDisplay('cancellation_reference', false);
            g_form.setDisplay('bk_to_bk_info', false);
            g_form.setDisplay('advice', true); //MSSCUSTODY-4883
            g_form.setReadOnly('advice', true); //MSSCUSTODY-4883

        }

        function settleTrade() {

            // Enable fields for Settle Trade Outcome
            g_form.setMandatory('value_date', true);
            g_form.setDisplay('value_date', true);
            g_form.setMandatory('settlement_date', false);
            g_form.setDisplay('settlement_date', true);
            g_form.setDisplay('settlement_date', true);
            g_form.setDisplay('settlement_type', true);
            g_form.setReadOnly('settlement_type', true);


            // Disabling fields for Settle Trade
            g_form.setValue('suspend', '');
            g_form.setMandatory('reason_code', false);
            g_form.setDisplay('reason_code', false);
            g_form.setValue('reason_code', '');
            g_form.setValue('reason_description', '');
            g_form.setLabelOf('reason_code', 'Reason Code');
            g_form.setMandatory('fxr_td', false);
            g_form.setDisplay('fxr_td', false);


        }

        function confirmTrade() {

            // Enable fields for Confirm Trade Outcome
            g_form.setMandatory('value_date', true);
            g_form.setDisplay('value_date', true);

            // Disabling fields for confirm trade
            g_form.setMandatory('settlement_type', false);
            g_form.setDisplay('settlement_type', false);
            g_form.setValue('settlement_type', '');
            g_form.setMandatory('settlement_date', false);
            g_form.setDisplay('settlement_date', false);
            g_form.setMandatory('reason_code', false);
            g_form.setDisplay('reason_code', false);
            g_form.setValue('reason_code', '');
            g_form.setValue('reason_description', '');
            g_form.setLabelOf('reason_code', 'Reason Code');
            g_form.setMandatory('fxr_td', false);
            g_form.setDisplay('fxr_td', false);
            g_form.setMandatory('cancellation_reference', false);
            g_form.setDisplay('cancellation_reference', false);
            g_form.setMandatory('bk_to_bk_info', false);
            g_form.setDisplay('bk_to_bk_info', false);

        }

        function processTradeCancellation(market, reasonCodeDCC, reasonCodeGC, fxLoc) {

            // Displaying fields for cancel Trade
            g_form.setMandatory('reason_code', true);
            g_form.setDisplay('reason_code', true);
            g_form.setDisplay('fxr_td', true);
            if (market == 'DCC UK') {
                g_form.setValue('reason_code', reasonCodeDCC); // Set reason code as 'CCANI' for DCC UK trades
            } else if (market == 'GC UK') {
                g_form.setValue('reason_code', reasonCodeGC); // Set reason code as 'CCANI' for GC UK trades
            }
            g_form.setReadOnly('reason_code', true);
            g_form.setMandatory('cancellation_reference', true);
            g_form.setDisplay('cancellation_reference', true);

            if ((fxLoc == 'L') || (fxLoc == 'O')) {
                g_form.setMandatory('fxr_td', true); // Make FXRTD mandatory when FX location is L or O.
            } else {
                g_form.setReadOnly('fxr_td', true); //Make FXRTD read only //MSSCUSTODY-4883
            }

            // Disabling fields for Cancel Trade
            g_form.setMandatory('settlement_type', false);
            g_form.setDisplay('settlement_type', false);
            g_form.setValue('settlement_type', '');
            g_form.setMandatory('settlement_date', false);
            g_form.setDisplay('settlement_date', false);
            g_form.setMandatory('value_date', false);
            g_form.setDisplay('value_date', false);
            g_form.setLabelOf('reason_code', 'Reason Code');
            g_form.setMandatory('bk_to_bk_info', false);
            g_form.setDisplay('bk_to_bk_info', false);

        }


    }

    function setOnLoadTaskForm(out_1) {

        g_form.setMandatory('settlement_date', out_1);
        g_form.setMandatory('value_date', out_1);
        g_form.setMandatory('fxr_td', out_1);
        g_form.setMandatory('reason_code', out_1);
        g_form.setMandatory('settlement_type', out_1);
        g_form.setMandatory('cancellation_reference', out_1);
        g_form.setMandatory('bk_to_bk_info', out_1);

        g_form.setDisplay('settlement_date', out_1);
        g_form.setDisplay('value_date', out_1);
        g_form.setDisplay('fxr_td', out_1);
        g_form.setDisplay('reason_code', out_1);
        g_form.setDisplay('settlement_type', out_1);
        g_form.setDisplay('cancellation_reference', out_1);
        g_form.setDisplay('bk_to_bk_info', out_1);

        g_form.clearValue('value_date');
        g_form.clearValue('settlement_date');
        g_form.clearValue('fxr_td');
        g_form.clearValue('reason_code');
        g_form.clearValue('reason_description');
        g_form.clearValue('settlement_type');
        g_form.clearValue('cancellation_reference');
        g_form.clearValue('bk_to_bk_info');

    }

}
